 auto* root=new QVBoxLayout(this); root->setContentsMargins(14,14,14,14); root->setSpacing(10); auto* title=new QLabel("EXPERIMENT RECORDING",this);title->setObjectName("title");root->addWidget(title);
 auto* panel=new QFrame(this);panel->setObjectName("panel");auto* pv=new QVBoxLayout(panel);auto* form=new QFormLayout(); form->setLabelAlignment(Qt::AlignRight|Qt::AlignVCenter);
