 peak_fields_=new QWidget(cp);auto* pg=new QGridLayout(peak_fields_);pg->setContentsMargins(0,0,0,0);peak_signal_=new QComboBox(peak_fields_);peak_signal_->addItems({"Velocity","Current","Torque","Applied voltage","Position","Electrical power","Mechanical power"});peak_threshold_=ds(peak_fields_,0,1e9,1,6,.1);peak_separation_s_=ds(peak_fields_,0,3600,.1,3,.05);peak_target_count_=new QSpinBox(peak_fields_);peak_target_count_->setRange(1,100000);peak_target_count_->setValue(5);peak_absolute_=new QCheckBox("Detect absolute magnitude peaks",peak_fields_);peak_absolute_->setChecked(true);pg->addWidget(new QLabel("Peak signal",peak_fields_),0,0);pg->addWidget(peak_signal_,0,1);pg->addWidget(new QLabel("Threshold",peak_fields_),0,2);pg->addWidget(peak_threshold_,0,3);pg->addWidget(new QLabel("Min separation [s]",peak_fields_),1,0);pg->addWidget(peak_separation_s_,1,1);pg->addWidget(new QLabel("Stop after",peak_fields_),1,2);pg->addWidget(peak_target_count_,1,3);pg->addWidget(peak_absolute_,2,0,1,4);cv->addWidget(peak_fields_);pv->addWidget(cp);
