QString RecordingDialog::directory()const{return directory_edit_->text().trimmed();} QString RecordingDialog::prefix()const{return prefix_edit_->text().trimmed();} QString RecordingDialog::notes()const{return notes_edit_->toPlainText();} bool RecordingDialog::writeMetadata()const noexcept{return metadata_check_->isChecked();}
models::RecordingConfig RecordingDialog::recordingConfig()const{models::RecordingConfig c;c.mode=static_cast<models::RecordingMode>(capture_mode_->currentIndex());c.sample_interval_ms=sample_interval_ms_->value();c.start_delay_s=start_delay_s_->value();c.duration_s=duration_s_->value();c.period_count=period_count_->value();c.peak_signal=static_cast<models::PeakSignal>(peak_signal_->currentIndex());c.peak_threshold=peak_threshold_->value();c.min_peak_distance_s=peak_separation_s_->value();c.peak_target_count=peak_target_count_->value();c.absolute_peaks=peak_absolute_->isChecked();return c;}
void RecordingDialog::setRecordingState(bool a){if(!a)state_label_->setText("IDLE");start_btn_->setEnabled(!a);stop_btn_->setEnabled(a);capture_mode_->setEnabled(!a);} void RecordingDialog::setStats(qint64 s,double sec,const QString& fpath){samples_label_->setText(QString::number(s));duration_label_->setText(QString::number(sec,'f',3)+" s");file_label_->setText(fpath.isEmpty()?"--":fpath);} void RecordingDialog::setPeakCount(int p){peaks_label_->setText(QString::number(p));} void RecordingDialog::setCaptureStatus(const QString& s){state_label_->setText(s);} void RecordingDialog::setWaveformInfo(const models::WaveformConfig& w){waveform_info_->setText(QString("Waveform: %1 · f=%2 Hz · duration=%3 s").arg(w.name()).arg(w.frequency_hz,0,'g',6).arg(w.duration_s,0,'g',6));} void RecordingDialog::showError(const QString& m){error_label_->setText(m);} void RecordingDialog::browseDirectory_(){const QString x=QFileDialog::getExistingDirectory(this,"Select data directory",directory());if(!x.isEmpty())directory_edit_->setText(x);} void RecordingDialog::updateCaptureModeUi_(){const auto m=static_cast<models::RecordingMode>(capture_mode_->currentIndex());timing_fields_->setVisible(m==models::RecordingMode::TimeWindow||m==models::RecordingMode::PeriodCount);duration_s_->setVisible(m==models::RecordingMode::TimeWindow);period_count_->setVisible(m==models::RecordingMode::PeriodCount);peak_fields_->setVisible(m==models::RecordingMode::PeakCount);}
